export const focusState=(mode='far',corrected=false)=>({near:mode==='near',lensWidth:mode==='near'?22:11,ligament:mode==='near'?'loose':'tight',focus:corrected?430:mode==='myopia'?370:mode==='hyperopia'?490:430});
